using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Threading;
namespace ImageNdi {
public sealed class AudioDecoder:IDisposable {
 public const int Rate=48000;
 readonly object gate=new object();readonly float[] ring=new float[Rate*4];int head,count;Process process;Thread worker;volatile bool stopping,ended;public volatile string Error;public readonly bool HasAudio;public long Underruns;readonly ManualResetEventSlim ready=new ManualResetEventSlim(false);int disposed;readonly string path;readonly bool loop;readonly double speed,startSeconds,outSeconds;
 static readonly ConcurrentDictionary<string,bool> audioTracks=new ConcurrentDictionary<string,bool>(StringComparer.OrdinalIgnoreCase);
 public static bool ContainsAudio(string path){var info=new FileInfo(path);string key=info.FullName+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks;bool found;if(audioTracks.TryGetValue(key,out found))return found;string probe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"video","ffprobe.exe");using(var p=new Process{StartInfo=new ProcessStartInfo(probe,"-v error -select_streams a:0 -show_entries stream=index -of csv=p=0 "+VideoTools.Quote(path)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){p.Start();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(5000)){try{p.Kill();}catch(InvalidOperationException){}throw new IOException("Analisi audio scaduta.");}if(p.ExitCode!=0)throw new IOException("Traccia audio non leggibile: "+error.Result);found=output.Result.Trim().Length>0;}if(audioTracks.Count>128)audioTracks.Clear();audioTracks[key]=found;return found;}
 public AudioDecoder(string path,bool loop,double speed=1,double startSeconds=0,double outSeconds=0){this.path=path;this.loop=loop;this.speed=speed;this.startSeconds=startSeconds;this.outSeconds=outSeconds;try{if(Double.IsNaN(speed)||Double.IsInfinity(speed)||speed<.5||speed>5)throw new ArgumentException("Velocità video non valida.");HasAudio=ContainsAudio(path);if(!HasAudio){ended=true;ready.Set();return;}process=StartDecoder();worker=new Thread(Read){IsBackground=true,Name="NDIPlayer audio decoder"};worker.Start();if(!ready.Wait(3000))Error="Audio non pronto: buffer iniziale non disponibile.";}catch(Exception e){Error=e.Message;ended=true;ready.Set();}}
 Process StartDecoder(){string tempo="";double remaining=speed;while(remaining>2){tempo+=",atempo=2";remaining/=2;}if(remaining!=1)tempo+=",atempo="+remaining.ToString("0.########",System.Globalization.CultureInfo.InvariantCulture);string start=startSeconds>0?"-ss "+startSeconds.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" ":"";string limit=outSeconds>0?"-t "+(outSeconds-startSeconds).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" ":"";return VideoTools.Start((loop&&outSeconds<=0?"-stream_loop -1 ":"")+start+"-i "+VideoTools.Quote(path)+" "+limit+"-map 0:a:0 -vn -sn -dn -af "+VideoTools.Quote("aresample=async=1000:first_pts=0"+tempo)+" -ac 2 -ar 48000 -c:a pcm_f32le -f f32le pipe:1");}
 void Read(){try{while(!stopping){var current=process;var errors=current.StandardError.ReadToEndAsync();var stream=current.StandardOutput.BaseStream;var bytes=new byte[8192];while(!stopping){int used=0;while(used<bytes.Length&&!stopping){int n=stream.Read(bytes,used,bytes.Length-used);if(n==0)break;used+=n;}if(used==0)break;int samples=used/8*2;var values=new float[samples];Buffer.BlockCopy(bytes,0,values,0,samples*4);Write(values);if(used<bytes.Length)break;}if(stopping)break;current.WaitForExit();if(current.ExitCode!=0){Error="Errore audio: "+errors.Result;break;}if(!loop||outSeconds<=0)break;current.Dispose();process=StartDecoder();}}catch(Exception e){if(!stopping)Error=e.Message;}finally{ended=true;ready.Set();lock(gate)Monitor.PulseAll(gate);}}
 void Write(float[] values){int offset=0;while(offset<values.Length&&!stopping){lock(gate){while(count==ring.Length&&!stopping)Monitor.Wait(gate);if(stopping)return;int tail=(head+count)%ring.Length,n=Math.Min(values.Length-offset,Math.Min(ring.Length-count,ring.Length-tail));Array.Copy(values,offset,ring,tail,n);offset+=n;count+=n;if(count>=Rate/5)ready.Set();}}}
 public int ReadStereo(float[] destination,int samples){Array.Clear(destination,0,samples);lock(gate){int read=Math.Min(count,samples);int first=Math.Min(read,ring.Length-head);Array.Copy(ring,head,destination,0,first);if(read>first)Array.Copy(ring,0,destination,first,read-first);head=(head+read)%ring.Length;count-=read;if(read<samples&&HasAudio&&!ended)Interlocked.Increment(ref Underruns);Monitor.PulseAll(gate);return read;}}
 public bool Finished {get{lock(gate)return ended&&count==0;}}
 public void Dispose(){if(Interlocked.Exchange(ref disposed,1)!=0)return;stopping=true;lock(gate)Monitor.PulseAll(gate);if(process!=null){try{if(!process.HasExited)process.Kill();}catch(InvalidOperationException){}if(worker!=null)worker.Join();try{process.WaitForExit(2000);}catch(InvalidOperationException){}process.Dispose();}ready.Dispose();}
}
}
